// =============================================
// ⚙️  INIT — Credentials & Global State Setup
// Edit LINE_TOKEN and LINE_GROUP_ID here
// LINE_CHANNEL_SECRET is used for signature validation
// =============================================

flow.set('LINE_TOKEN', env.get('LINE_TOKEN'));
flow.set('LINE_GROUP_ID', env.get('LINE_GROUP_ID'));
flow.set('LINE_CHANNEL_SECRET', env.get('LINE_CHANNEL_SECRET'));


// Initialise state store only if empty (survives redeploy)
if (!flow.get('machines')) flow.set('machines', {});

// machineState schema per entry:
// {
//   state:           'NORMAL' | 'WARNING' | 'CRITICAL',
//   latched:         false,
//   acknowledged:    false,
//   snoozeUntil:     0,
//   lastEscalation:  0,
//   backoffUntil:    0,
//   stateChangedAt:  timestamp,
//   lastAlertSentAt: 0
// }

node.status({fill:'green', shape:'dot', text:'LINE config loaded ✓'});
return null;

// Extract plant + machine_id from MQTT topic
// Topic: factory/{plant}/machine/{machine_id}/vibration
var parts = msg.topic.split('/');
var p = msg.payload;

msg.plant      = parts[1] || p.plant      || 'UNKNOWN';
msg.machine_id = parts[3] || p.machine_id || 'UNKNOWN';
msg.sensor_id  = p.sensor_id || 'UNKNOWN';

if (!p.timestamp) p.timestamp = new Date().toISOString();
msg.timestamp = p.timestamp;

p.plant      = msg.plant;
p.machine_id = msg.machine_id;

return msg;

// ════════════════════════════════════════════════════════════════════
//  ⏱️  Latency Calculator
//  Computes data pipeline latency: device timestamp → Node-RED receive
//
//  p.timestamp  = ISO8601 set by ESP32 at measurement time
//  receive_time = Date.now() at this Node-RED function
//
//  Fields written to InfluxDB:
//    data_latency_ms  — current latency (ms)
//
//  Flow context (for anomaly detection):
//    latency_history_{machine_id} — last 10 readings
// ════════════════════════════════════════════════════════════════════

const p        = msg.payload;
const machineId = p.machine_id || msg.machine_id || 'UNKNOWN';

// ── 1. RECEIVE TIMESTAMP ───────────────────────────────────────────
const receiveMs = Date.now();           // ms since epoch, Node-RED server time

// ── 2. PARSE DEVICE TIMESTAMP ─────────────────────────────────────
let deviceMs = null;
if (p.timestamp) {
    const d = new Date(p.timestamp);
    if (!isNaN(d.getTime())) {
        deviceMs = d.getTime();
    }
}

// ── 3. CALCULATE LATENCY ──────────────────────────────────────────
let latencyMs = null;
if (deviceMs !== null) {
    latencyMs = receiveMs - deviceMs;
    // Sanity check: reject negative or extreme values (> 5 minutes)
    if (latencyMs < 0 || latencyMs > 300000) {
        node.warn(`[Latency] Suspicious value ${latencyMs}ms for ${machineId} — skipping`);
        latencyMs = null;
    }
}

// ── 4. WRITE TO PAYLOAD ───────────────────────────────────────────
if (latencyMs !== null) {
    p.data_latency_ms = Math.round(latencyMs);
} else {
    // Use 0 as fallback so InfluxDB always has a value
    // Grafana filters out 0 differently from null/undefined
    p.data_latency_ms = 0;
}

// ── 5. ROLLING LATENCY HISTORY (flow context) ────────────────────
// Store last 10 readings for anomaly detection
const histKey = 'latency_history_' + machineId;
let hist = flow.get(histKey) || [];
if (latencyMs !== null) {
    hist.push(latencyMs);
    if (hist.length > 10) hist.shift();
    flow.set(histKey, hist);
}

// ── 6. NODE STATUS ────────────────────────────────────────────────
const color = latencyMs === null    ? 'grey'
            : latencyMs > 3000      ? 'red'
            : latencyMs > 1000      ? 'yellow' : 'green';

node.status({
    fill:  color,
    shape: 'dot',
    text:  latencyMs === null
           ? `${machineId}: no timestamp`
           : `${machineId}: ${p.data_latency_ms}ms`
});

return msg;

// =============================================
// 🧠 Health Logic — Edge-Only Mode
// =============================================
// ESP32 v5.5+ คำนวณและส่งมาครบทุก field:
//   alarm_level, health_score, crest_factor, alarm_code
//
// Node-RED ทำหน้าที่:
//   1. Validate required fields → DROP ถ้าขาด
//   2. ใช้ค่าจาก edge โดยตรง — ไม่คำนวณซ้ำ
// =============================================
const WARNING_RMS  = 4.5;
const CRITICAL_RMS = 7.1;

var p = msg.payload;

// ════════════════════════════════════════════
// GUARD: DROP ถ้า field หลักขาดหรือผิดปกติ
// ทุก field ด้านล่างนี้ต้องมีครบ — ขาด field ใด
// ค่าที่เหลือทั้งหมดไม่มีความหมาย → DROP ทิ้ง
// ════════════════════════════════════════════

function drop(reason, value) {
    node.warn('[Health] ❌ DROP — ' + reason + ' (got: "' + value + '") | machine=' + (p.machine_id || 'unknown'));
    node.status({ fill: 'red', shape: 'ring', text: '❌ DROP: ' + reason });
    return true;
}

// 1. machine_id
if (!p.machine_id)
    return drop('machine_id missing', p.machine_id), null;

// 2. rms — ค่าหลัก ถ้าขาดแล้วทุกอย่างไม่มีความหมาย
var rms = parseFloat(p.rms);
if (isNaN(rms) || rms < 0)
    return drop('rms missing/invalid', p.rms), null;

// 3. alarm_level — ต้องเป็นค่าที่กำหนดเท่านั้น
if (!['NORMAL','WARNING','CRITICAL'].includes(p.alarm_level))
    return drop('alarm_level missing/invalid', p.alarm_level), null;

// 4. health_score — ต้องเป็นตัวเลข 0–100
var hs = parseFloat(p.health_score);
if (isNaN(hs) || hs < 0 || hs > 100)
    return drop('health_score missing/invalid', p.health_score), null;

// 5. crest_factor — ต้องเป็นตัวเลข >= 0
var cf = parseFloat(p.crest_factor);
if (isNaN(cf) || cf < 0)
    return drop('crest_factor missing/invalid', p.crest_factor), null;

// ════════════════════════════════════════════
// ✅ ทุก field ผ่าน — ใช้ค่าจาก edge โดยตรง
// ════════════════════════════════════════════

// alarm_code: ใช้จาก edge ถ้ามี ไม่งั้น derive จาก alarm_level
if (p.alarm_code === undefined) {
    p.alarm_code = p.alarm_level === 'CRITICAL' ? 2 :
                   p.alarm_level === 'WARNING'  ? 1 : 0;
}

p.thresholds = { warning: WARNING_RMS, critical: CRITICAL_RMS };

// ── Status badge ──────────────────────────────────────────────
var color = p.alarm_level === 'CRITICAL' ? 'red'
          : p.alarm_level === 'WARNING'  ? 'yellow' : 'green';

node.status({ fill: color, shape: 'dot',
    text: '⚡ ' + p.machine_id +
          ' RMS:'  + rms.toFixed(2) +
          ' H:'    + hs  + '%' +
          ' CF:'   + cf  +
          ' ['     + p.alarm_level + ']'
});

return msg;

// =============================================
// UNIFIED STATE ENGINE
// - Manages per-machine state in flow context
// - Rule 1: No duplicate alerts for same state
// - Rule 4: Recovery (CRITICAL→NORMAL) → send once
// - Respects snooze, ack, backoff
// =============================================
var machineId  = msg.payload.machine_id || 'UNKNOWN';
var newLevel   = msg.payload.alarm_level || 'NORMAL';
var now        = Date.now();

var machines = flow.get('machines') || {};

// Bootstrap machine entry
if (!machines[machineId]) {
    machines[machineId] = {
        state: 'NORMAL', latched: false, acknowledged: false,
        snoozeUntil: 0, lastEscalation: 0, backoffUntil: 0,
        stateChangedAt: now, lastAlertSentAt: 0
    };
}
var m = machines[machineId];

// --- Guard: backoff from 429 ---
if (now < m.backoffUntil) {
    var wait = Math.ceil((m.backoffUntil - now) / 1000);
    node.status({fill:'orange', shape:'ring',
        text: machineId + ': backoff ' + wait + 's'});
    flow.set('machines', machines);
    return null;
}

// --- Guard: snoozed ---
if (now < m.snoozeUntil) {
    var remain = Math.ceil((m.snoozeUntil - now) / 60000);
    node.status({fill:'grey', shape:'ring',
        text: machineId + ': snoozed ' + remain + 'm'});
    flow.set('machines', machines);
    return null;
}

// --- Rule 1: Same state → drop (unless latch reset) ---
if (m.state === newLevel && !m.latched) {
    node.status({fill:'grey', shape:'dot',
        text: machineId + ': same (' + newLevel + '), skip'});
    flow.set('machines', machines);
    return null;
}

// --- State transition ---
var prevState = m.state;
m.state          = newLevel;
m.latched        = false;
m.acknowledged   = false;
m.stateChangedAt = now;
if (newLevel !== 'NORMAL') {
    m.lastEscalation = 0; // reset escalation timer on new alarm
}

flow.set('machines', machines);

// --- Set alert type for downstream ---
msg._machineId = machineId;
msg._prevState = prevState;
msg._alertType = (newLevel === 'NORMAL') ? 'recovery' : 'alert';

node.status({fill: newLevel === 'CRITICAL' ? 'red' : newLevel === 'WARNING' ? 'yellow' : 'green',
    shape:'dot', text: machineId + ': ' + prevState + ' → ' + newLevel});

return msg;

// =============================================
// LINE MESSAGE BUILDER
// Handles: alert | escalation | recovery
// Checks backoff & snooze before sending
// =============================================
var accessToken = flow.get('LINE_TOKEN');
var groupId     = flow.get('LINE_GROUP_ID');
var p           = msg.payload;
var mId         = msg._machineId || (p.machine_id || 'N/A').toUpperCase();
var alertType   = msg._alertType || 'alert';

if (!accessToken || accessToken === 'YOUR_CHANNEL_ACCESS_TOKEN_HERE') {
    node.warn('LINE_TOKEN not set!');
    node.status({fill:'red', shape:'dot', text:'No token!'});
    return null;
}

// Re-check machine state (may have been snoozed since state engine ran)
var machines = flow.get('machines') || {};
var m = machines[mId];
if (m) {
    var now = Date.now();
    if (now < m.snoozeUntil || now < m.backoffUntil) return null;
    m.lastAlertSentAt = now;
    flow.set('machines', machines);
}

var timeThai = new Date().toLocaleString('th-TH', {
    timeZone:'Asia/Bangkok', hour12:false,
    year:'numeric', month:'short', day:'numeric',
    hour:'2-digit', minute:'2-digit', second:'2-digit'
}) + ' น.';

var rms  = typeof p.rms === 'number' ? p.rms.toFixed(2) : '?';
var text = '';

if (alertType === 'alert') {
    var emoji = p.alarm_level === 'CRITICAL' ? '🚨' : '⚠️';
    text = emoji + ' แจ้งเตือน ' + p.alarm_level + '!\n'
         + '🏭 Plant: '   + (p.plant || 'N/A') + '\n'
         + '⚙️ Machine: ' + mId + '\n'
         + '📊 RMS: '     + rms + ' mm/s\n'
         + '❤️ Health: '  + (p.health_score || '?') + '%\n'
         + '⏰ '          + timeThai + '\n\n'
         + '📖 Commands:\n'
         + '  ack '    + mId + '\n'
         + '  snooze ' + mId + ' 30';

} else if (alertType === 'escalation') {
    text = '🔴 ESCALATION!\n'
         + '🏭 Plant: '          + (p.plant || 'N/A') + '\n'
         + '⚙️ Machine: '        + mId + '\n'
         + '⏱️ CRITICAL มานาน: ' + (msg._durationMin || '?') + ' นาที\n'
         + '📊 RMS: '            + rms + ' mm/s\n'
         + '⏰ '                 + timeThai + '\n\n'
         + '⚠️ กรุณาตรวจสอบด่วน!';

} else if (alertType === 'recovery') {
    text = '✅ กลับสู่ NORMAL\n'
         + '⚙️ Machine: ' + mId + '\n'
         + '📊 RMS: '     + rms + ' mm/s\n'
         + '⏰ '          + timeThai;
}

flow.set('_lastMachine', mId);
msg._machineId = mId;
msg.headers = {
    'Content-Type':  'application/json',
    'Authorization': 'Bearer ' + accessToken
};
msg.payload = {
    to: groupId,
    messages: [{type:'text', text:text}]
};

node.status({fill:'blue', shape:'dot',
    text:'[' + alertType + '] → ' + mId});
return msg;

// =============================================
// 429 RESPONSE HANDLER
// 200 → success, clear backoff
// 429 → set backoffUntil = now + 5min, reset latch
// 4xx/5xx → log with detail
// =============================================
const BACKOFF_MS = 5 * 60 * 1000; // 5 minutes
var code      = msg.statusCode;
var machineId = msg._machineId || flow.get('_lastMachine') || 'UNKNOWN';

var machines = flow.get('machines') || {};
var m = machines[machineId];

if (code === 200) {
    if (m) { m.backoffUntil = 0; }
    flow.set('machines', machines);
    node.status({fill:'green', shape:'dot', text:'✓ ' + machineId});
    return [msg, null];

} else if (code === 429) {
    if (m) {
        m.backoffUntil = Date.now() + BACKOFF_MS;
        m.latched      = true; // force resend after backoff
    }
    flow.set('machines', machines);
    node.warn('🚫 LINE 429: ' + machineId + ' → backoff 5min');
    node.status({fill:'red', shape:'ring', text:'429 backoff 5min: ' + machineId});
    return [null, null];

} else {
    var body = '';
    try { body = JSON.stringify(msg.payload); } catch(e) {}
    node.warn('LINE API Error ' + code + ': ' + body);
    node.status({fill:'red', shape:'dot', text:'Error ' + code + ': ' + machineId});
    return [msg, null];
}

// =============================================
// ESCALATION TIMER (Rule 2)
// Runs every 1 minute
// Sends escalation if:
//   - Machine is CRITICAL
//   - Not snoozed / backoff
//   - Not acknowledged
//   - In CRITICAL > 10 min
//   - Escalation not yet sent for this alarm
// =============================================
const ESCALATION_MS = 10 * 60 * 1000; // 10 min
var now      = Date.now();
var machines = flow.get('machines') || {};
var results  = [];

Object.keys(machines).forEach(function(mId) {
    var m = machines[mId];
    if (m.state !== 'CRITICAL')           return;
    if (m.acknowledged)                   return;
    if (now < m.snoozeUntil)              return;
    if (now < m.backoffUntil)             return;
    if (m.lastEscalation > m.stateChangedAt) return; // already escalated this alarm
    if ((now - m.stateChangedAt) < ESCALATION_MS) return;

    m.lastEscalation = now;
    results.push({
        _alertType:    'escalation',
        _machineId:    mId,
        _durationMin:  Math.floor((now - m.stateChangedAt) / 60000),
        payload: { machine_id: mId, plant: 'PLANT01', alarm_level: 'CRITICAL', rms: 0 }
    });
});

flow.set('machines', machines);

if (results.length === 0) {
    node.status({fill:'grey', shape:'ring', text:'no escalation needed'});
    return null;
}
node.status({fill:'yellow', shape:'dot',
    text:'Escalating: ' + results.map(function(r){return r._machineId;}).join(', ')});

return results;

// Check snooze expiry every minute
// If expired → push LINE notification + unblock
var ACCESS_TOKEN = flow.get('LINE_TOKEN');
var GROUP_ID     = flow.get('LINE_GROUP_ID');
var now          = Date.now();
var machines     = flow.get('machines') || {};
var expired      = [];

Object.keys(machines).forEach(function(mId) {
    var m = machines[mId];
    if (m.snoozeUntil > 0 && now >= m.snoozeUntil) {
        expired.push(mId);
        m.snoozeUntil = 0;
    }
});

flow.set('machines', machines);

var activeSnoozed = Object.keys(machines).filter(function(mId){
    return machines[mId].snoozeUntil > now;
});
node.status(activeSnoozed.length > 0
    ? {fill:'grey', shape:'ring', text:'Snoozed: ' + activeSnoozed.join(', ')}
    : {fill:'green', shape:'dot', text:'All clear'});

if (expired.length === 0) return null;

var resumeText = '🔔 Snooze หมดเวลา — กลับมาแจ้งเตือน:\n';
expired.forEach(function(m) { resumeText += '\n✅ ' + m; });
resumeText += '\n\n⏰ ' + new Date().toLocaleString('th-TH', {timeZone:'Asia/Bangkok'});

msg.headers = {
    'Content-Type':  'application/json',
    'Authorization': 'Bearer ' + ACCESS_TOKEN
};
msg.payload = { to: GROUP_ID, messages: [{type:'text', text:resumeText}] };
return msg;

// =============================================
// LINE SIGNATURE VALIDATION
// X-Line-Signature: Base64(HMAC-SHA256(body, channelSecret))
// Node-RED does not have built-in crypto in sandbox,
// so we use the global 'crypto' module via node context.
// If validation fails → respond 401 and drop.
// =============================================
var secret    = flow.get('LINE_CHANNEL_SECRET') || '';
var signature = msg.req.headers['x-line-signature'] || '';
var rawBody   = msg.req.rawBody || JSON.stringify(msg.payload);

// Store rawBody for downstream if needed
msg._rawBody   = rawBody;
msg._signature = signature;

if (!secret || secret === 'YOUR_CHANNEL_SECRET_HERE') {
    // Skip validation in dev mode — warn loudly
    node.warn('⚠️  Signature validation SKIPPED — set LINE_CHANNEL_SECRET in Init node');
    node.status({fill:'yellow', shape:'ring', text:'sig: skipped (no secret)'});
    return [msg, null];
}

try {
    var crypto = global.get('crypto') || require('crypto');
    var hash   = crypto.createHmac('SHA256', secret).update(rawBody).digest('base64');
    if (hash === signature) {
        node.status({fill:'green', shape:'dot', text:'sig: OK'});
        return [msg, null]; // valid → output 1
    } else {
        node.warn('❌ Signature mismatch! Dropping request.');
        node.status({fill:'red', shape:'dot', text:'sig: INVALID'});
        msg.statusCode = 401;
        msg.payload    = {error: 'Invalid signature'};
        return [null, msg]; // invalid → output 2 (401 response)
    }
} catch(e) {
    node.warn('Crypto error: ' + e.message);
    return [msg, null]; // fallback: pass through
}

// CRITICAL: respond 200 within 1 second
// Do NOT await any processing here
// LINE will retry if no 200 within 1s
msg.statusCode = 200;
msg.payload    = {};
return msg;

// =============================================
// INTERACTIVE COMMAND PARSER v3
// Supported commands:
//   ack <machineId>            → stop escalation, mark acknowledged
//   snooze <machineId> <min>   → mute X minutes
//   status                     → summary of all machines
//   reset <machineId>          → clear latched state
//   help                       → list commands
// =============================================

var ACCESS_TOKEN = flow.get('LINE_TOKEN');
var MAX_SNOOZE_MIN = 480; // 8 hours

var events = (msg.payload && msg.payload.events) || [];
if (events.length === 0) return null;

var event = events[0];
if (event.type !== 'message' || event.message.type !== 'text') return null;

var rawText    = (event.message.text || '').trim();
var replyToken = event.replyToken;
var userId     = (event.source && event.source.userId) || 'unknown';
var machines   = flow.get('machines') || {};
var now        = Date.now();
var replyText  = '';

function thaiTime(d) {
    return (d || new Date()).toLocaleString('th-TH', {
        timeZone:'Asia/Bangkok', hour12:false,
        year:'numeric', month:'short', day:'numeric',
        hour:'2-digit', minute:'2-digit'
    }) + ' น.';
}

function ensureMachine(mId) {
    if (!machines[mId]) {
        machines[mId] = {
            state:'NORMAL', latched:false, acknowledged:false,
            snoozeUntil:0, lastEscalation:0, backoffUntil:0,
            stateChangedAt:now, lastAlertSentAt:0
        };
    }
    return machines[mId];
}

var cmd = rawText.toLowerCase();

// ── ACK <machineId> ─────────────────────────────
var ackMatch = rawText.match(/^ack\s+(\S+)$/i);
if (ackMatch) {
    var mId = ackMatch[1].toUpperCase();
    var m   = ensureMachine(mId);
    m.acknowledged  = true;
    m.lastEscalation = now; // suppress further escalation
    flow.set('machines', machines);
    replyText = '✅ ACK: ' + mId + '\n'
              + '📋 Escalation หยุดแล้ว\n'
              + '⚠️ Alert ยังทำงานอยู่ถ้า state เปลี่ยน\n'
              + '⏰ ' + thaiTime();
    node.status({fill:'green', shape:'dot', text:'ACK: ' + mId});
}

// ── SNOOZE <machineId> <minutes> ────────────────
var snoozeMatch = rawText.match(/^snooze\s+(\S+)\s+(\d+)$/i);
if (snoozeMatch) {
    var mId  = snoozeMatch[1].toUpperCase();
    var mins = parseInt(snoozeMatch[2]);
    if (mins > MAX_SNOOZE_MIN) mins = MAX_SNOOZE_MIN;
    var m = ensureMachine(mId);
    m.snoozeUntil = now + (mins * 60000);
    flow.set('machines', machines);
    replyText = '🔇 Snooze: ' + mId + '\n'
              + '⏱️ ' + mins + ' นาที\n'
              + '📅 เปิดอีกครั้ง: ' + thaiTime(new Date(m.snoozeUntil)) + '\n'
              + '💡 พิมพ์ reset ' + mId + ' เพื่อยกเลิก snooze ก่อนเวลา';
    node.status({fill:'grey', shape:'ring', text:'SNOOZE ' + mins + 'm: ' + mId});
}

// ── STATUS ──────────────────────────────────────
if (cmd === 'status' || cmd === 'สถานะ') {
    var critical = [], warning = [], snoozed = [], acked = [];
    Object.keys(machines).forEach(function(mId) {
        var m = machines[mId];
        if (m.state === 'CRITICAL') critical.push(mId);
        if (m.state === 'WARNING')  warning.push(mId);
        if (now < m.snoozeUntil)   snoozed.push(mId + '(' + Math.ceil((m.snoozeUntil-now)/60000) + 'm)');
        if (m.acknowledged)         acked.push(mId);
    });
    replyText = '📊 สถานะระบบ\n'
              + '────────────────\n'
              + '🔴 CRITICAL: ' + (critical.length || '0') + (critical.length ? ' — ' + critical.join(', ') : '') + '\n'
              + '🟡 WARNING:  ' + (warning.length  || '0') + (warning.length  ? ' — ' + warning.join(', ')  : '') + '\n'
              + '🔇 Snoozed: '  + (snoozed.length  || '0') + (snoozed.length  ? '\n   ' + snoozed.join('\n   ') : '') + '\n'
              + '✅ Acked:   '  + (acked.length     || '0') + (acked.length    ? ' — ' + acked.join(', ')    : '') + '\n'
              + '────────────────\n'
              + '⏰ ' + thaiTime();
    node.status({fill:'blue', shape:'dot', text:'STATUS replied'});
}

// ── RESET <machineId> ───────────────────────────
var resetMatch = rawText.match(/^reset\s+(\S+)$/i);
if (resetMatch) {
    var mId = resetMatch[1].toUpperCase();
    machines[mId] = {
        state:'NORMAL', latched:false, acknowledged:false,
        snoozeUntil:0, lastEscalation:0, backoffUntil:0,
        stateChangedAt:now, lastAlertSentAt:0
    };
    flow.set('machines', machines);
    replyText = '🔄 RESET: ' + mId + '\n'
              + '✅ State ถูกล้างแล้ว\n'
              + '🔔 ระบบพร้อมแจ้งเตือนใหม่\n'
              + '⏰ ' + thaiTime();
    node.status({fill:'yellow', shape:'dot', text:'RESET: ' + mId});
}

// ── HELP ────────────────────────────────────────
if (cmd === 'help' || cmd === 'ช่วยเหลือ') {
    replyText = '📖 คำสั่งที่รองรับ\n'
              + '────────────────\n'
              + '✅ ack PUMP01\n'
              + '   → หยุด escalation\n\n'
              + '🔇 snooze PUMP01 30\n'
              + '   → ปิดแจ้งเตือน 30 นาที\n\n'
              + '📊 status\n'
              + '   → ดูสถานะทุกเครื่อง\n\n'
              + '🔄 reset PUMP01\n'
              + '   → ล้าง state ให้ส่งใหม่\n\n'
              + '⏰ ' + thaiTime();
    node.status({fill:'blue', shape:'dot', text:'HELP replied'});
}

if (!replyText || !replyToken) return null;

msg.headers = {
    'Content-Type':  'application/json',
    'Authorization': 'Bearer ' + ACCESS_TOKEN
};
msg.payload = {
    replyToken: replyToken,
    messages: [{type:'text', text:replyText}]
};
return msg;

flow.set('machines', {});
node.status({fill:'yellow', shape:'dot', text:'All state cleared'});
node.warn('⚠️ All machine state cleared');
return null;

// ════════════════════════════════════════════════════════════════════
//  📊 Prepare InfluxDB (Edge-Only) v7
//  Updated for ESP32 firmware v15.2
//  Changes from v6:
//    - Fix: peak_x → vel_peak_x (v15.0 field name)
//    - Fix: dominant_axis ← p.kurtosis_axis (v15.1 field name)
//    - Add: vel_peak_y, vel_peak_z
//    - Add: cf_x, cf_y, cf_z (per-axis Crest Factor)
//    - Add: kurtosis_x, kurtosis_y, kurtosis_z (per-axis)
//    - Add: bearing_alert string field + bearing_alert_code enum
//    - Add: freq_drift_x/y/z, freq_alert, freq_gate_open
//  node-red-contrib-influxdb → msg.payload = [fields, tags]
// ════════════════════════════════════════════════════════════════════

const p = msg.payload;

// ── 1. VALIDATE ────────────────────────────────────────────────────
if (!p || typeof p !== 'object') {
    node.status({ fill: 'red', shape: 'ring', text: 'Invalid payload' });
    return null;
}

// ── 2. TAGS — ONLY stable identity fields ─────────────────────────
// Do NOT put dynamic state values here.
// Dynamic tags cause InfluxDB series explosion/cardinality issues.
const tags = {
    plant:      String(p.plant      ?? 'UNKNOWN'),
    machine_id: String(p.machine_id ?? 'UNKNOWN'),
    sensor_id:  String(p.sensor_id  ?? 'UNKNOWN'),
};

// ── 3. FIELDS — all measurements & dynamic states ─────────────────
const fields = {};

const numericFields = [

    // ── Core vibration (RMS estimated) ───────────────────────────
    ['rms',  p.rms],
    ['vx',   p.vx],
    ['vy',   p.vy],
    ['vz',   p.vz],

    // ── True peak velocity (v15.0) ────────────────────────────────
    // Raw register value / 100 before ÷√2 conversion
    ['peak',        p.peak],          // peak hold (window max)
    ['vel_peak_x',  p.vel_peak_x],    // per-axis true peak X
    ['vel_peak_y',  p.vel_peak_y],    // per-axis true peak Y
    ['vel_peak_z',  p.vel_peak_z],    // per-axis true peak Z

    // ── Crest Factor — per axis + max (v15.1) ────────────────────
    ['crest_factor', p.crest_factor], // = cf_max (dominant)
    ['cf_x',         p.cf_x],
    ['cf_y',         p.cf_y],
    ['cf_z',         p.cf_z],

    // ── Kurtosis — per axis + max (v15.1) ────────────────────────
    // Gaussian baseline = 3.0 | early warning > 4.0 | confirmed > 6.0
    ['kurtosis_max', p.kurtosis_max], // max(KX, KY, KZ)
    ['kurtosis_x',   p.kurtosis_x],
    ['kurtosis_y',   p.kurtosis_y],
    ['kurtosis_z',   p.kurtosis_z],

    // ── Health & alarms ───────────────────────────────────────────
    ['health_score', p.health_score],
    ['alarm_code',   p.alarm_code],

    // ── Environment ───────────────────────────────────────────────
    ['temp', p.temp],

    // ── Frequency analysis ────────────────────────────────────────
    ['freq_x',       p.freq_x],
    ['freq_y',       p.freq_y],
    ['freq_z',       p.freq_z],
    ['freq_ratio_x', p.freq_ratio_x],
    ['freq_ratio_y', p.freq_ratio_y],
    ['freq_ratio_z', p.freq_ratio_z],

    // ── Frequency drift (v15.2) ───────────────────────────────────
    // Suppressed to 0 when rpm < RPM_FREQ_GATE (400 rpm)
    ['freq_drift_x', p.freq_drift_x],
    ['freq_drift_y', p.freq_drift_y],
    ['freq_drift_z', p.freq_drift_z],

    // ── Machine utilization ───────────────────────────────────────
    ['rpm',                    p.rpm],
    ['state',                  p.state],
    ['operating_hours_total',  p.operating_hours_total],
    ['rotation_signal_ok',     p.rotation_signal_ok],

    // ── Sensor / pipeline health ──────────────────────────────────
    ['sync_age_s',       p.sync_age_s],
    ['data_latency_ms',  p.data_latency_ms],

    // ── Maintenance analytics ─────────────────────────────────────
    ['maintenance_risk_score', p.maintenance_risk_score],
    ['fault_confidence',       p.fault_confidence],
];

// ── Numeric field validation ──────────────────────────────────────
numericFields.forEach(([key, val]) => {
    const n = Number(val);
    if (val !== undefined && val !== null && !isNaN(n)) {
        fields[key] = n;
    }
});

// ── 4. STRING STATE FIELDS (dynamic values) ───────────────────────
// IMPORTANT: Must be fields, NOT tags.
fields.alarm_level    = String(p.alarm_level    ?? 'NORMAL');
fields.sensor_status  = String(p.sensor_status  ?? 'UNKNOWN');
fields.fault_type     = String(p.fault_type     ?? 'UNKNOWN');

// v15.1: dominant axis comes from kurtosis_axis field
// (v6 read p.dominant_axis which doesn't exist in v15.x payloads)
fields.dominant_axis  = String(p.dominant_vibration_axis  ?? p.dominant_axis ?? 'UNKNOWN');

// v15.2: bearing alert classification
// Values: "NORMAL" | "EARLY_WARNING" | "CONFIRMED" | "INVALID_STATE"
fields.bearing_alert  = String(p.bearing_alert  ?? 'UNKNOWN');

// ── 5. BOOLEAN → INTEGER ──────────────────────────────────────────
if (p.time_synced !== undefined) {
    fields.time_synced = p.time_synced ? 1 : 0;
}

// v15.2: freq gate and alert (boolean → integer)
if (p.freq_gate_open !== undefined) {
    fields.freq_gate_open = p.freq_gate_open ? 1 : 0;
}
if (p.freq_alert !== undefined) {
    fields.freq_alert = p.freq_alert ? 1 : 0;
}

// ── 6. ENUM → INTEGER CODES ───────────────────────────────────────
// Faster Grafana/Influx queries than string filtering.

// fault_type
const faultTypeMap = {
    UNKNOWN:      0,
    UNBALANCE:    1,
    MISALIGNMENT: 2,
    RESONANCE:    3,
    BEARING:      4,
    LOOSENESS:    5,
    CAVITATION:   6,
    IMBALANCE:    1,   // alias
};
fields.fault_type_code = faultTypeMap[p.fault_type] ?? 0;

// sensor_status
const sensorStatusMap = { ONLINE: 1, OFFLINE: 0, ERROR: 2 };
fields.sensor_status_code = sensorStatusMap[p.sensor_status] ?? -1;

// dominant_axis (kurtosis_axis in v15.1+)
const axisMap = { X: 1, Y: 2, Z: 3 };
const axisSource = p.dominant_vibration_axis ?? p.dominant_axis ?? 'UNKNOWN';
fields.dominant_axis_code = axisMap[axisSource] ?? 0;
const kurtosisAxisSource =
    p.kurtosis_axis ??
    'UNKNOWN';

fields.kurtosis_axis_code =
    axisMap[kurtosisAxisSource] ?? 0;

// bearing_alert (v15.2)
const bearingAlertMap = {
    NORMAL:        0,
    EARLY_WARNING: 1,
    CONFIRMED:     2,
    INVALID_STATE: -1,
};
fields.bearing_alert_code = bearingAlertMap[p.bearing_alert] ?? 0;

// predictive_status (legacy field, keep for backward compat)
const predictiveStatusMap = { GOOD: 0, WARNING: 1, HIGH_RISK: 2 };
if (p.predictive_status !== undefined) {
    fields.predictive_status_code = predictiveStatusMap[p.predictive_status] ?? 0;
}

// ── 7. VALIDATE REQUIRED FIELDS ───────────────────────────────────
if (Object.keys(fields).length === 0 || fields.rms === undefined) {
    node.status({ fill: 'red', shape: 'ring', text: 'NO VALID FIELDS' });
    return null;
}

// ── 8. MEASUREMENT ────────────────────────────────────────────────
msg.measurement = 'vibration';

// ── 9. TIMESTAMP ──────────────────────────────────────────────────
// Use ESP32 RTC timestamp if synchronized. Fallback to Node-RED time.
if (p.timestamp && p.time_synced === true) {
    const ts = new Date(p.timestamp);
    msg.timestamp = (ts.getFullYear() > 2020) ? ts : new Date();
} else {
    msg.timestamp = new Date();
}

// ── 10. PAYLOAD ───────────────────────────────────────────────────
msg.payload = [fields, tags];

// ── 11. STATUS BADGE ──────────────────────────────────────────────
const alarmCode   = fields.alarm_code   ?? 0;
const riskScore   = fields.maintenance_risk_score ?? 0;
const bearingCode = fields.bearing_alert_code ?? 0;

const color =
    alarmCode === 2   ? 'red'    :
    alarmCode === 1   ? 'yellow' :
    bearingCode === 2 ? 'red'    :   // CONFIRMED bearing fault
    bearingCode === 1 ? 'orange' :   // EARLY_WARNING
    riskScore >= 75   ? 'orange' : 'green';

node.status({
    fill: color,
    shape: 'dot',
    text:
        `⚡${tags.machine_id}` +
        ` RMS:${(fields.rms ?? 0).toFixed(2)}` +
        ` K:${(fields.kurtosis_max ?? 0).toFixed(2)}(${fields.kurtosis_axis})` +
        ` BRG:${fields.bearing_alert}` +
        ` [${fields.fault_type}]`
});

return msg;

// ════════════════════════════════════════════════════════════════════
//  🔬 Maintenance Analytics v2 — Multi-Feature Fault Classification
//  Replaces single freq_ratio_x rule with evidence-scoring engine
//
//  Inputs expected from ESP32 (all numeric):
//    rms, vx, vy, vz, peak, crest_factor, kurtosis,
//    freq_ratio_x, dominant_freq, health_score
//
//  Outputs added to payload:
//    fault_type, fault_confidence, fault_scores,
//    dominant_axis, maintenance_risk_score, predictive_status
// ════════════════════════════════════════════════════════════════════

const p = msg.payload;
const num = (v) => { const n = Number(v); return isNaN(n) ? null : n; };

// ── 1. PARSE INPUTS ─────────────────────────────────────────────────
const rms      = num(p.rms)           ?? 0;
const vx       = num(p.vx)            ?? 0;
const vy       = num(p.vy)            ?? 0;
const vz       = num(p.vz)            ?? 0;
const peak     = num(p.peak)          ?? 0;
const cf       = num(p.crest_factor)  ?? 0;
const kurt     = num(p.kurtosis)      ?? 3.0;   // 3.0 = Gaussian healthy baseline
const ratioX   = num(p.freq_ratio_x)  ?? 0;
const domFreq  = num(p.dominant_freq) ?? 0;
const hs       = num(p.health_score)  ?? 100;

// ── 2. DOMINANT AXIS ─────────────────────────────────────────────────
// Which radial axis carries the highest vibration energy?
let dominant_axis;
if      (vx >= vy && vx >= vz) dominant_axis = "X";
else if (vy >= vx && vy >= vz) dominant_axis = "Y";
else                           dominant_axis = "Z";

// ── 3. DERIVED HELPER RATIOS ─────────────────────────────────────────
// Peak / RMS ratio (independent of the sensor's own crest_factor field;
// used as corroborating impulsiveness evidence)
const peakRmsRatio = (rms > 0) ? (peak / rms) : 0;

// Axial-to-radial ratio (misalignment excites axial mode strongly)
const maxRadial  = Math.max(vx, vy);
const axialRatio = (maxRadial > 0) ? (vz / maxRadial) : 0;

// Non-integer frequency ratio fraction
// e.g. ratioX=1.0 → frac=0.0 (clean 1× RPM = imbalance)
// e.g. ratioX=2.35 → frac=0.35 (non-harmonic = bearing defect freq)
const freqFrac = ratioX % 1;

// ════════════════════════════════════════════════════════════════════
// 4. EVIDENCE SCORING ENGINE
//
// Each fault type accumulates evidence points (0–12 typical range).
// Multiple indicators vote independently.  Highest scorer wins,
// subject to a minimum threshold and explicit safety overrides.
//
// Why scoring instead of rigid IF/ELSE?
//   Real machinery rarely shows a textbook-perfect single signature.
//   Combining weak evidence from several sensors reduces false alarms
//   far better than any single threshold can.
// ════════════════════════════════════════════════════════════════════

const scores = { BEARING: 0, RESONANCE: 0, MISALIGNMENT: 0, IMBALANCE: 0 };

// ─── BEARING FAULT evidence ─────────────────────────────────────────
// ISO 10816 / ISO 13373: Early bearing defects produce high-energy
// impulses at defect frequencies (BPFO, BPFI, BSF, FTF).
// These impulses raise kurtosis and crest_factor well before RMS rises.
//
//  kurtosis:    healthy ≈ 3.0  |  incipient fault > 4  |  severe > 6
//  crest_factor: healthy 1.4–3 |  fault > 4            |  severe > 6
//  peak/rms:    impulsive if ratio >> nominal crest_factor

if      (kurt > 8)   scores.BEARING += 4;   // Severe bearing damage
else if (kurt > 6)   scores.BEARING += 3;   // Significant defect
else if (kurt > 4)   scores.BEARING += 2;   // Incipient bearing fault
else if (kurt > 3.5) scores.BEARING += 1;

if      (cf > 7)     scores.BEARING += 3;
else if (cf > 5)     scores.BEARING += 2;
else if (cf > 3.5)   scores.BEARING += 1;

if      (peakRmsRatio > 7) scores.BEARING += 2;
else if (peakRmsRatio > 5) scores.BEARING += 1;

// Non-integer dominant frequency ≠ clean harmonic → bearing defect freq
if (ratioX > 0 && freqFrac > 0.25 && freqFrac < 0.75) scores.BEARING += 1;

// Bearing early stage: impulsive but RMS still low
// (kurtosis high, rms moderate → weight bearing even more)
if (kurt > 4 && rms < 4.5) scores.BEARING += 1;

// ─── RESONANCE evidence ─────────────────────────────────────────────
// Resonance occurs when excitation frequency locks onto a structural
// natural frequency. Signature: very high freq_ratio, elevated RMS at
// ONE dominant frequency, low kurtosis (smooth, not impulsive).

if      (ratioX > 10) scores.RESONANCE += 4;
else if (ratioX > 7)  scores.RESONANCE += 3;
else if (ratioX > 5)  scores.RESONANCE += 2;
else if (ratioX > 4)  scores.RESONANCE += 1;

if      (rms > 11.0)  scores.RESONANCE += 2;
else if (rms > 7.1)   scores.RESONANCE += 1;

// Resonance is NOT impulsive — penalise if kurtosis/CF is high
// (high impulsiveness → bearing, not resonance)
if (kurt > 5)  scores.RESONANCE -= 2;
if (cf > 5)    scores.RESONANCE -= 1;

// ─── MISALIGNMENT evidence ──────────────────────────────────────────
// Angular / parallel misalignment creates strong 2× and 3× RPM harmonics
// and raises axial vibration because the coupling deflects in all planes.
// freq_ratio 1.3–3.5, axial component clearly elevated.

if      (ratioX >= 1.8 && ratioX <= 2.5) scores.MISALIGNMENT += 3; // Classic 2× zone
else if (ratioX >= 1.3 && ratioX <= 3.5) scores.MISALIGNMENT += 2;

if      (axialRatio > 0.7) scores.MISALIGNMENT += 3; // Very high axial → severe misalign
else if (axialRatio > 0.5) scores.MISALIGNMENT += 2;
else if (axialRatio > 0.3) scores.MISALIGNMENT += 1;

// Moderate kurtosis (not clean sine, not highly impulsive)
if (kurt >= 3.0 && kurt <= 5.0) scores.MISALIGNMENT += 1;

// Penalty if bearing indicators dominate
if (kurt > 6) scores.MISALIGNMENT -= 2;
if (cf > 6)   scores.MISALIGNMENT -= 1;

// ─── IMBALANCE evidence ─────────────────────────────────────────────
// Mass imbalance produces a pure sinusoidal force at exactly 1× RPM.
// Signature: freq_ratio ≈ 1.0, very low kurtosis (≈3), low CF,
// radial dominant (imbalance is a centrifugal radial force).

if      (ratioX >= 0.85 && ratioX < 1.15) scores.IMBALANCE += 4; // Tight 1× zone
else if (ratioX >= 0.7  && ratioX < 1.4)  scores.IMBALANCE += 2;

// Gaussian vibration (low kurtosis)
if      (kurt >= 2.5 && kurt <= 3.5) scores.IMBALANCE += 3; // Near-perfect sine
else if (kurt > 3.5  && kurt <= 4.5) scores.IMBALANCE += 1;

// Low crest factor = non-impulsive sine wave
if      (cf >= 1.4 && cf <= 2.5) scores.IMBALANCE += 2;
else if (cf > 2.5 && cf <= 3.5)  scores.IMBALANCE += 1;

// Purely radial (X or Y dominant, Z relatively low)
if ((dominant_axis === 'X' || dominant_axis === 'Y') && axialRatio < 0.3)
    scores.IMBALANCE += 1;

// Penalty: if freq ratio is away from 1× or impulsive, it is not imbalance
if (ratioX > 2.5 || ratioX < 0.5) scores.IMBALANCE -= 2;
if (kurt > 5)                      scores.IMBALANCE -= 2;

// ── 5. CLASSIFY FROM SCORES ─────────────────────────────────────────
// Minimum evidence threshold: at least 3 points to classify
// (avoids classifying noise as a fault)
const MIN_SCORE  = 3;
const FAULT_PRIORITY = ['BEARING', 'RESONANCE', 'MISALIGNMENT', 'IMBALANCE'];

let fault_type = "UNKNOWN";
let fault_confidence = 0;

// Clamp negative scores to zero
Object.keys(scores).forEach(k => { if (scores[k] < 0) scores[k] = 0; });

const maxScore = Math.max(...Object.values(scores));

if (ratioX <= 0 || maxScore < MIN_SCORE) {
    fault_type = "UNKNOWN";
} else {
    // Rank all faults by score
    const ranked = Object.entries(scores).sort((a, b) => b[1] - a[1]);
    const topScore = ranked[0][1];
    const runnerUp = ranked[1] ? ranked[1][1] : 0;

    if (topScore - runnerUp <= 1) {
        // Tie (within 1 point) → apply safety priority
        const tiedFaults = ranked.filter(([, s]) => topScore - s <= 1).map(([k]) => k);
        fault_type = FAULT_PRIORITY.find(f => tiedFaults.includes(f));
    } else {
        fault_type = ranked[0][0];
    }

    // Confidence: proportion of max possible score
    fault_confidence = Math.min(100, Math.round((topScore / 12) * 100));
}

// ── 6. HARD SAFETY OVERRIDES ─────────────────────────────────────────
// When indicators are extreme, trust the physics over the scoring.
// These cannot be voted away by other features.

if (kurt > 10 && cf > 7) {
    fault_type = "BEARING";             // Unmistakable impulse pattern
    fault_confidence = 99;
}
if (ratioX > 12 && kurt < 4.5) {
    fault_type = "RESONANCE";           // Extreme high-order excitation
    fault_confidence = 95;
}

// ── 7. MAINTENANCE RISK SCORE ────────────────────────────────────────
// Combines RMS severity AND fault type urgency.
// Bearing early-stage: low RMS but high kurtosis → still medium risk
let maintenance_risk_score;
const rmsRisk = rms > 11.0 ? 95 : rms > 7.1 ? 75 : rms > 4.5 ? 50 : 20;
const faultBoost = (fault_type === 'BEARING' && kurt > 4 && rms < 4.5) ? 25 : 0;
maintenance_risk_score = Math.min(100, rmsRisk + faultBoost);

// ── 8. PREDICTIVE STATUS ─────────────────────────────────────────────
let predictive_status;
if      (hs > 70) predictive_status = "GOOD";
else if (hs >= 50) predictive_status = "WARNING";
else              predictive_status = "HIGH_RISK";

// ── 9. WRITE RESULTS TO PAYLOAD ──────────────────────────────────────
p.dominant_axis           = dominant_axis;
p.fault_type              = fault_type;
p.fault_confidence        = fault_confidence;
p.fault_scores            = scores;                  // debug: all category scores
p.maintenance_risk_score  = maintenance_risk_score;
p.predictive_status       = predictive_status;

// ── 10. NODE STATUS BADGE ─────────────────────────────────────────────
const riskColor = maintenance_risk_score >= 75 ? 'red'
                : maintenance_risk_score >= 50 ? 'yellow' : 'green';

node.status({
    fill:  riskColor,
    shape: 'dot',
    text:  `${p.machine_id} | ${fault_type}(${fault_confidence}%) | Axis:${dominant_axis} | Risk:${maintenance_risk_score}% | ${predictive_status}`
});

return msg;
